-- Tabelas: users, products, categories, customers, orders, order_items, suppliers, purchases, purchase_items, stock_movements, pos_sales, pos_sale_items, cash_registers, cash_transactions, accounts_payable, accounts_receivable, crm_leads, crm_deals, crm_activities

DROP TABLE IF EXISTS "users" CASCADE;
CREATE TABLE "users" (
  "id" BIGINT DEFAULT nextval('users_id_seq'::regclass) NOT NULL,
  "name" CHARACTER VARYING(150) NOT NULL,
  "email" CHARACTER VARYING(255) NOT NULL,
  "password_hash" CHARACTER VARYING(255) NOT NULL,
  "role" USER-DEFINED DEFAULT 'operator'::user_role NOT NULL,
  "is_active" BOOLEAN DEFAULT true NOT NULL,
  "failed_login_attempts" INTEGER DEFAULT 0 NOT NULL,
  "locked_until" TIMESTAMP WITHOUT TIME ZONE,
  "last_login_at" TIMESTAMP WITHOUT TIME ZONE,
  "last_login_ip" CHARACTER VARYING(45),
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "products" CASCADE;
CREATE TABLE "products" (
  "id" BIGINT DEFAULT nextval('products_id_seq'::regclass) NOT NULL,
  "name" CHARACTER VARYING(255) NOT NULL,
  "sku" CHARACTER VARYING(50),
  "description" TEXT,
  "price" NUMERIC DEFAULT 0 NOT NULL,
  "cost" NUMERIC DEFAULT 0 NOT NULL,
  "stock" INTEGER DEFAULT 0 NOT NULL,
  "stock_min" INTEGER DEFAULT 5 NOT NULL,
  "category_id" BIGINT,
  "image_url" TEXT,
  "is_active" BOOLEAN DEFAULT true NOT NULL,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "barcode" CHARACTER VARYING(60),
  "price_shopee" NUMERIC,
  "video_url" TEXT,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "categories" CASCADE;
CREATE TABLE "categories" (
  "id" BIGINT DEFAULT nextval('categories_id_seq'::regclass) NOT NULL,
  "name" CHARACTER VARYING(100) NOT NULL,
  "description" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "customers" CASCADE;
CREATE TABLE "customers" (
  "id" BIGINT DEFAULT nextval('customers_id_seq'::regclass) NOT NULL,
  "name" CHARACTER VARYING(255) NOT NULL,
  "email" CHARACTER VARYING(255),
  "phone" CHARACTER VARYING(20),
  "document" CHARACTER VARYING(20),
  "is_active" BOOLEAN DEFAULT true NOT NULL,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "address_street" CHARACTER VARYING(255),
  "address_number" CHARACTER VARYING(20),
  "address_complement" CHARACTER VARYING(100),
  "address_district" CHARACTER VARYING(100),
  "address_city" CHARACTER VARYING(100),
  "address_state" CHARACTER(2),
  "address_zip" CHARACTER VARYING(10),
  "customer_type" CHARACTER VARYING(10) DEFAULT 'pf'::character varying NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "orders" CASCADE;
CREATE TABLE "orders" (
  "id" BIGINT DEFAULT nextval('orders_id_seq'::regclass) NOT NULL,
  "order_number" CHARACTER VARYING(50) NOT NULL,
  "customer_id" BIGINT,
  "status" CHARACTER VARYING(20) DEFAULT 'pending'::character varying NOT NULL,
  "total" NUMERIC DEFAULT 0 NOT NULL,
  "items_count" INTEGER DEFAULT 0 NOT NULL,
  "shipping_address" JSONB,
  "payment_method" CHARACTER VARYING(50),
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "discount" NUMERIC DEFAULT 0 NOT NULL,
  "shipping_cost" NUMERIC DEFAULT 0 NOT NULL,
  "channel" CHARACTER VARYING(30) DEFAULT 'manual'::character varying NOT NULL,
  "tracking_code" CHARACTER VARYING(100),
  "notes" TEXT,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "order_items" CASCADE;
CREATE TABLE "order_items" (
  "id" BIGINT DEFAULT nextval('order_items_id_seq'::regclass) NOT NULL,
  "order_id" BIGINT NOT NULL,
  "product_id" BIGINT NOT NULL,
  "quantity" INTEGER DEFAULT 1 NOT NULL,
  "price" NUMERIC NOT NULL,
  "subtotal" NUMERIC NOT NULL,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "suppliers" CASCADE;
CREATE TABLE "suppliers" (
  "id" BIGINT DEFAULT nextval('suppliers_id_seq'::regclass) NOT NULL,
  "name" CHARACTER VARYING(255) NOT NULL,
  "email" CHARACTER VARYING(255),
  "phone" CHARACTER VARYING(20),
  "document" CHARACTER VARYING(20),
  "contact_name" CHARACTER VARYING(150),
  "address_street" CHARACTER VARYING(255),
  "address_city" CHARACTER VARYING(100),
  "address_state" CHARACTER(2),
  "address_zip" CHARACTER VARYING(10),
  "is_active" BOOLEAN DEFAULT true NOT NULL,
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "status" CHARACTER VARYING(50) DEFAULT 'pending'::character varying,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "purchases" CASCADE;
CREATE TABLE "purchases" (
  "id" BIGINT DEFAULT nextval('purchases_id_seq'::regclass) NOT NULL,
  "supplier_id" BIGINT NOT NULL,
  "purchase_number" CHARACTER VARYING(50),
  "status" CHARACTER VARYING(20) DEFAULT 'pending'::character varying NOT NULL,
  "total" NUMERIC DEFAULT 0 NOT NULL,
  "notes" TEXT,
  "created_by" BIGINT,
  "received_at" TIMESTAMP WITHOUT TIME ZONE,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "number" CHARACTER VARYING(50),
  "total_amount" NUMERIC DEFAULT 0,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "purchase_items" CASCADE;
CREATE TABLE "purchase_items" (
  "id" BIGINT DEFAULT nextval('purchase_items_id_seq'::regclass) NOT NULL,
  "purchase_id" BIGINT NOT NULL,
  "product_id" BIGINT NOT NULL,
  "quantity" INTEGER DEFAULT 1 NOT NULL,
  "unit_price" NUMERIC DEFAULT 0 NOT NULL,
  "total_price" NUMERIC DEFAULT 0 NOT NULL,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "stock_movements" CASCADE;
CREATE TABLE "stock_movements" (
  "id" BIGINT DEFAULT nextval('stock_movements_id_seq'::regclass) NOT NULL,
  "product_id" BIGINT NOT NULL,
  "type" CHARACTER VARYING(30) NOT NULL,
  "quantity" INTEGER NOT NULL,
  "balance" INTEGER NOT NULL,
  "reference_type" CHARACTER VARYING(30),
  "reference_id" BIGINT,
  "notes" TEXT,
  "created_by" BIGINT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "pos_sales" CASCADE;
CREATE TABLE "pos_sales" (
  "id" BIGINT DEFAULT nextval('pos_sales_id_seq'::regclass) NOT NULL,
  "operation_number" CHARACTER VARYING(30) NOT NULL,
  "customer_id" BIGINT,
  "seller_id" BIGINT NOT NULL,
  "cash_register_id" BIGINT,
  "status" CHARACTER VARYING(20) DEFAULT 'cart'::character varying NOT NULL,
  "subtotal" NUMERIC DEFAULT 0 NOT NULL,
  "discount" NUMERIC DEFAULT 0 NOT NULL,
  "total" NUMERIC DEFAULT 0 NOT NULL,
  "payment_method" CHARACTER VARYING(30),
  "payment_details" JSONB,
  "notes" TEXT,
  "is_pre_sale" BOOLEAN DEFAULT false NOT NULL,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "completed_at" TIMESTAMP WITHOUT TIME ZONE,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "pos_sale_items" CASCADE;
CREATE TABLE "pos_sale_items" (
  "id" BIGINT DEFAULT nextval('pos_sale_items_id_seq'::regclass) NOT NULL,
  "pos_sale_id" BIGINT NOT NULL,
  "product_id" BIGINT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "price" NUMERIC NOT NULL,
  "subtotal" NUMERIC NOT NULL,
  "barcode_scanned" CHARACTER VARYING(60),
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "cash_registers" CASCADE;
CREATE TABLE "cash_registers" (
  "id" BIGINT DEFAULT nextval('cash_registers_id_seq'::regclass) NOT NULL,
  "operator_id" BIGINT NOT NULL,
  "opened_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "closed_at" TIMESTAMP WITHOUT TIME ZONE,
  "opening_balance" NUMERIC DEFAULT 0 NOT NULL,
  "closing_balance" NUMERIC,
  "expected_balance" NUMERIC,
  "status" CHARACTER VARYING(20) DEFAULT 'open'::character varying NOT NULL,
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "cash_transactions" CASCADE;
CREATE TABLE "cash_transactions" (
  "id" BIGINT DEFAULT nextval('cash_transactions_id_seq'::regclass) NOT NULL,
  "register_id" BIGINT NOT NULL,
  "type" CHARACTER VARYING(30) NOT NULL,
  "amount" NUMERIC NOT NULL,
  "reference_type" CHARACTER VARYING(30),
  "reference_id" BIGINT,
  "payment_method" CHARACTER VARYING(50),
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "accounts_payable" CASCADE;
CREATE TABLE "accounts_payable" (
  "id" BIGINT DEFAULT nextval('accounts_payable_id_seq'::regclass) NOT NULL,
  "supplier_id" BIGINT,
  "purchase_id" BIGINT,
  "description" CHARACTER VARYING(255) NOT NULL,
  "amount" NUMERIC NOT NULL,
  "due_date" DATE NOT NULL,
  "paid_at" TIMESTAMP WITHOUT TIME ZONE,
  "payment_method" CHARACTER VARYING(50),
  "status" CHARACTER VARYING(20) DEFAULT 'pending'::character varying NOT NULL,
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "accounts_receivable" CASCADE;
CREATE TABLE "accounts_receivable" (
  "id" BIGINT DEFAULT nextval('accounts_receivable_id_seq'::regclass) NOT NULL,
  "order_id" BIGINT,
  "description" CHARACTER VARYING(255),
  "amount" NUMERIC NOT NULL,
  "due_date" DATE NOT NULL,
  "paid_at" TIMESTAMP WITHOUT TIME ZONE,
  "payment_method" CHARACTER VARYING(50),
  "status" CHARACTER VARYING(20) DEFAULT 'pending'::character varying NOT NULL,
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "crm_leads" CASCADE;
CREATE TABLE "crm_leads" (
  "id" INTEGER DEFAULT nextval('crm_leads_id_seq'::regclass) NOT NULL,
  "user_id" INTEGER NOT NULL,
  "company" CHARACTER VARYING(255),
  "contact_name" CHARACTER VARYING(255) NOT NULL,
  "email" CHARACTER VARYING(255),
  "phone" CHARACTER VARYING(50),
  "source" CHARACTER VARYING(100) DEFAULT 'manual'::character varying,
  "status" CHARACTER VARYING(50) DEFAULT 'new'::character varying NOT NULL,
  "value" NUMERIC DEFAULT 0,
  "notes" TEXT,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT now(),
  "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(),
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "crm_deals" CASCADE;
CREATE TABLE "crm_deals" (
  "id" INTEGER DEFAULT nextval('crm_deals_id_seq'::regclass) NOT NULL,
  "lead_id" INTEGER NOT NULL,
  "user_id" INTEGER NOT NULL,
  "title" CHARACTER VARYING(255) NOT NULL,
  "description" TEXT,
  "pipeline_stage" CHARACTER VARYING(50) DEFAULT 'prospecting'::character varying NOT NULL,
  "expected_value" NUMERIC DEFAULT 0,
  "close_date" DATE,
  "probability" INTEGER DEFAULT 50,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT now(),
  "updated_at" TIMESTAMP WITH TIME ZONE DEFAULT now(),
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "crm_activities" CASCADE;
CREATE TABLE "crm_activities" (
  "id" INTEGER DEFAULT nextval('crm_activities_id_seq'::regclass) NOT NULL,
  "lead_id" INTEGER,
  "deal_id" INTEGER,
  "user_id" INTEGER NOT NULL,
  "type" CHARACTER VARYING(50) NOT NULL,
  "subject" CHARACTER VARYING(255),
  "description" TEXT,
  "scheduled_at" TIMESTAMP WITH TIME ZONE,
  "completed_at" TIMESTAMP WITH TIME ZONE,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT now(),
  PRIMARY KEY ("id")
);


