INSERT INTO "products" ("id", "name", "sku", "description", "price", "cost", "stock", "stock_min", "category_id", "image_url", "is_active", "created_at", "updated_at", "barcode", "price_shopee", "video_url") VALUES ('1628', 'Batom matte', NULL, 'Arraste para o lado para ver as cores Batom Matte "O Poder do Florescer" é um verdadeiro tesouro para os amantes de maquiagem. Com sua fórmula de alta qualidade e acabamento matte impecável, esse batom oferece uma experiência única aos seus usuários. Além de realçar os lábios com cores intensas e sofisticadas, esse produto também é uma escolha consciente, uma vez que é certificado como "não testado em animais". Sua formulação cuidadosa garante lábios hidratados e livres de ressecamento, proporcionando conforto durante todo o dia.', '5.90', '0.00', 99, 0, NULL, '6', true, '2026-10-21T20:37:00.051Z', '2026-10-21T20:37:00.051Z', NULL, '11.73', NULL);
INSERT INTO "products" ("id", "name", "sku", "description", "price", "cost", "stock", "stock_min", "category_id", "image_url", "is_active", "created_at", "updated_at", "barcode", "price_shopee", "video_url") VALUES ('1629', 'Sabonete íntimo UVA com sensação térmica', NULL, 'Com sensação térmica.  Extratos de aroeira, barbatimão e malva Ph equilibrado  Sabonete íntimo Uva foi especialmente desenvolvido para a higiene diária. Sua fórmula suave possui extratos naturais aus oferecem cuidados para a pele delicada da região íntima, proporcionando uma agradável sensação de limpeza, segurança e bem estar.', '10.00', '0.00', 99, 0, NULL, '1', true, '2026-10-21T20:37:00.052Z', '2026-10-21T20:37:00.052Z', NULL, '16.61', NULL);
INSERT INTO "products" ("id", "name", "sku", "description", "price", "cost", "stock", "stock_min", "category_id", "image_url", "is_active", "created_at", "updated_at", "barcode", "price_shopee", "video_url") VALUES ('1630', 'Corretivo', NULL, 'Este corretivo líquido foi especialmente formulado para cobrir imperfeições e realçar seus traços mais bonitos.  Sua textura leve e cremosa se espalha suavemente sobre a pele, proporcionando uma cobertura perfeita e um acabamento impecável. Independentemente do seu tipo de pele, ○ Corretivo Líquido Lua & Neve LN02168 se adapta facilmente, criando uma tela suave para a aplicação de outros produtos de maquiagem. Este corretivo é conhecido por sua fórmula de longa duração, que camufla olheiras, manchas, imperfeições e descolorações, deixando sua pele com uma aparência renovada e radiante. Ele é versátil o suficiente para ser usado tanto para o dia a dia quanto para ocasiões especiais.', '12.00', '0.00', 99, 0, NULL, '3', true, '2026-10-21T20:37:00.052Z', '2026-10-21T20:37:00.052Z', NULL, '18.99', NULL);
